def pins(c, k, a, b):
    """k's relation at (τa, σb) by itself fixes δ_E to the target's determined answer there."""
    p, E, w = c.p, c.E, c.deltaE
    if w not in E.foot[k] or not c.translates(a, b):
        return False
    y = p.ans(a, b)
    if y is BOT:
        return False
    i = E.foot[k].index(w)
    return set(t[i] for t in E.L(k, c.tau[a], c.sigma[b])) == {y}


